//! The export request -> encoder request derivation, held to today's JavaScript: every record of
//! `fixtures/video-export-jobs.tsv` (generated by `scripts/generate-video-export-fixtures.mjs` from
//! `videoExportArguments`, `encodeNativeVideo`'s checks and the service's `validateConfig`) must come out the same,
//! errors included.

use std::collections::HashMap;

use styk_core::export::{plan_video, AudioClip, JobContext, Stage, VideoFields};
use styk_services::video::codec_dimensions;

const FIXTURE: &str = include_str!("fixtures/video-export-jobs.tsv");

fn unescape(text: &str) -> String {
    let mut out = String::new();
    let mut chars = text.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('t') => out.push('\t'),
                Some('n') => out.push('\n'),
                Some(other) => out.push(other),
                None => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn record(line: &str) -> HashMap<String, String> {
    line.split('\t').filter_map(|field| field.split_once('=')).map(|(k, v)| (k.to_string(), unescape(v))).collect()
}

fn number(fields: &HashMap<String, String>, key: &str) -> f64 {
    fields[key].parse().unwrap_or_else(|_| panic!("{key} = {:?}", fields[key]))
}

fn same(a: f64, b: f64) -> bool {
    a == b
}

#[test]
fn every_record_of_the_fixture_comes_out_the_same() {
    let (mut ok, mut errors) = (0, 0);
    for (n, line) in FIXTURE.lines().enumerate() {
        let r = record(line);
        let fields = VideoFields {
            format: r["format"].clone(),
            width: number(&r, "width"),
            height: number(&r, "height"),
            from: number(&r, "from"),
            to: number(&r, "to"),
            smoothing: r["smoothing"].clone(),
            video_quality: r["videoQuality"].clone(),
            bitrate_mode: r["bitrateMode"].clone(),
            bitrate_mbps: number(&r, "bitrateMbps"),
            codec_mp4: r.get("codecMp4").cloned().unwrap_or_default(),
            codec_avi: r.get("codecAvi").cloned().unwrap_or_default(),
            audio: r["audio"] == "true",
            name: r.get("name").cloned(),
        };
        let mut context = JobContext::new(number(&r, "totalFrames"), number(&r, "fps"), r.get("nameContext").map_or("", String::as_str));
        context.audio_clips = r
            .get("clips")
            .map(|clips| clips.split(',').filter(|c| !c.is_empty()).map(|c| c.split_once(':').unwrap()).map(|(s, d)| AudioClip { start: s.parse().unwrap(), duration: d.parse().unwrap() }).collect())
            .unwrap_or_default();
        let context_line = format!("record {n}: {line}");
        let planned = plan_video(&fields, &context);
        let stage = match r["stage"].as_str() {
            "request" => Stage::Request,
            "native" => Stage::Native,
            "service" => Stage::Service,
            _ => Stage::Request,
        };
        if r["stage"] != "ok" {
            let error = planned.as_ref().err().unwrap_or_else(|| panic!("expected an error: {context_line}"));
            assert_eq!(error.stage, stage, "{context_line}");
            let expected = &r["error"];
            // A key is compared whole; a message that has no key is the English text.
            assert_eq!(&error.id, expected, "{context_line}");
            errors += 1;
            continue;
        }
        let job = planned.unwrap_or_else(|e| panic!("{e}: {context_line}"));
        let o = |key: &str| number(&r, &format!("o.{key}"));
        assert!(same(job.options.width, o("width")) && same(job.options.height, o("height")), "{context_line}");
        assert!(same(job.options.start, o("start")) && same(job.options.end, o("end")) && same(job.options.quality, o("quality")), "{context_line}");
        assert_eq!(job.options.smoothing, r["o.smoothing"], "{context_line}");
        assert!(same(job.fps, o("fps")) && same(job.ticks, o("ticks")), "{context_line}");
        assert_eq!(job.codec.as_deref(), r.get("o.codec").map(String::as_str), "{context_line}");
        assert_eq!(job.extension, r["o.extension"], "{context_line}");
        assert_eq!(job.filename, r["o.filename"], "{context_line}");
        assert_eq!(job.include_audio, r["o.includeAudio"] == "true", "{context_line}");
        assert!(same(job.rate_quality, o("rateQuality")), "{context_line}");
        assert_eq!(job.rate_bitrate, r.get("o.rateBitrate").map(|b| b.parse::<f64>().unwrap()), "{context_line}");
        let c = &job.encode;
        assert_eq!(c.container.parse_id(), r["c.format"], "{context_line}");
        assert_eq!(c.codec.id(), r["c.codec"], "{context_line}");
        assert!(same(c.width as f64, number(&r, "c.width")) && same(c.height as f64, number(&r, "c.height")), "{context_line}");
        let (ew, eh, _) = codec_dimensions(c.codec, c.width, c.height);
        assert!(same(ew as f64, number(&r, "c.encodedWidth")) && same(eh as f64, number(&r, "c.encodedHeight")), "{context_line}");
        assert!(same(c.fps, number(&r, "c.fps")) && same(c.total_frames as f64, number(&r, "c.totalFrames")), "{context_line}");
        assert!(same(c.rate.quality, number(&r, "c.quality")) && same(c.max_bytes as f64, number(&r, "c.maxBytes")), "{context_line}");
        assert_eq!(c.rate.bitrate, r.get("c.bitrate").map(|b| b.parse::<f64>().unwrap()), "{context_line}");
        assert_eq!(c.audio, r["c.audio"] == "true", "{context_line}");
        ok += 1;
    }
    println!("{ok} jobs and {errors} refusals agree with the JavaScript");
    assert!(ok > 1000 && errors > 1000);
}

trait ParseId {
    fn parse_id(&self) -> &'static str;
}

impl ParseId for styk_services::video::Container {
    fn parse_id(&self) -> &'static str {
        match self {
            styk_services::video::Container::Webm => "webm",
            styk_services::video::Container::Mp4 => "mp4",
            styk_services::video::Container::Avi => "avi",
            styk_services::video::Container::Asf => "wmv",
        }
    }
}
